{-# LANGUAGE OverloadedStrings #-}

-- | The random grammars of the fixture @test/random/Differential.txt@, on which the
-- interpreter is compared with the generated parser (ADR 0090).
--
-- The fixture is @test/random/Differential.txt@, and its module
-- @Fixture.Differential@ is generated by @scripts/regen-fixtures.sh@.
-- Fifty small grammars are made from a fixed seed, after the generator of
-- the label tests of peg-grammar (@genGrammar@), with left recursion,
-- labels with recovery rules and messages, @%expect@, @%nomemo@, @%token@,
-- @%inline@ and bindings. Each one passes the checks on its own; their
-- rules are told apart by a prefix, and their start rules are the entries
-- of the fixture. The generator has a pseudo-random number generator of
-- its own (SplitMix), so that the grammars do not depend on the version of
-- a library.
module Differential
  ( differentialGrammar
  , differentialEntries
  , differentialInputs
  ) where

import Data.Bits (shiftR, xor)
import Data.Text (Text)
import qualified Data.Text as T
import Data.Word (Word64)
import Peg.Grammar.Check (check)
import Peg.Grammar.Parser (parseGrammar)

-- | The text of @test/random/Differential.txt@. It is not among the
-- fixtures of @test/fixtures@, and its extension is not @.hpeg@, since
-- @peg-hs lint@, @peg-hs fmt@ and the tests of the repository's grammars
-- would find in it labels without effect and alternatives that never
-- succeed.
differentialGrammar :: Text
differentialGrammar =
  T.unlines $
    [ "# The random grammars of ADR 0090, made by the tests from the seed " <> T.pack (show seed) <> "."
    , "# Do not edit: the tests compare this file with the generator (test/Differential.hs)."
    , "%module Fixture.Differential"
    , "%syntax"
    ]
      ++ ["%entry " <> e | e <- drop 1 differentialEntries]
      ++ concatMap smallDirectives grammars
      ++ concatMap smallRules grammars
  where
    grammars = smallGrammars

-- | The start rules of the grammars: the first is the start rule of the
-- fixture, and the others are its entries.
differentialEntries :: [Text]
differentialEntries = [smallPrefix g <> "S" | g <- smallGrammars]

-- | Every string of a, b and c of length 4 or less.
differentialInputs :: [Text]
differentialInputs = map T.pack (concatMap (\n -> sequence (replicate n "abc")) [0 .. 4 :: Int])

seed :: Word64
seed = 90

-- A small grammar: its prefix, directives and rules.
data Small = Small
  { smallPrefix :: Text
  , smallDirectives :: [Text]
  , smallRules :: [Text]
  }

smallGrammars :: [Small]
smallGrammars = go 1 (seed * 1000)
  where
    go :: Int -> Word64 -> [Small]
    go k s
      | k > 50 = []
      | otherwise =
          let p = "D" <> T.pack (show k) <> "_"
              (g, s') = runR (genSmall p) s
           in if valid g then g : go (k + 1) s' else go k s'
    valid g = either (const False) (const True) (parseGrammar (standalone g) >>= check)
    standalone g = T.unlines (["%module M", "%syntax"] ++ smallDirectives g ++ smallRules g)

-- A pseudo-random generator ---------------------------------------------------------

newtype R a = R {runR :: Word64 -> (a, Word64)}

instance Functor R where
  fmap f (R g) = R $ \s -> let (a, s') = g s in (f a, s')

instance Applicative R where
  pure x = R $ \s -> (x, s)
  R f <*> R x = R $ \s -> let (f', s') = f s; (x', s'') = x s' in (f' x', s'')

instance Monad R where
  R g >>= k = R $ \s -> let (a, s') = g s in runR (k a) s'

-- SplitMix64.
word :: R Word64
word = R $ \s ->
  let s' = s + 0x9E3779B97F4A7C15
      z1 = (s' `xor` (s' `shiftR` 30)) * 0xBF58476D1CE4E5B9
      z2 = (z1 `xor` (z1 `shiftR` 27)) * 0x94D049BB133111EB
   in (z2 `xor` (z2 `shiftR` 31), s')

-- An integer from lo to hi.
choose :: Int -> Int -> R Int
choose lo hi = (\w -> lo + fromIntegral (w `mod` fromIntegral (hi - lo + 1))) <$> word

elements :: [a] -> R a
elements xs = (xs !!) <$> choose 0 (length xs - 1)

frequency :: [(Int, R a)] -> R a
frequency xs = choose 1 (sum (map fst xs)) >>= pick xs
  where
    pick ((w, g) : rest) k
      | k <= w = g
      | otherwise = pick rest (k - w)
    pick [] _ = error "frequency: no choice"

chance :: Int -> R Bool
chance n = (== 0) <$> choose 0 (n - 1)

vectorOf :: Int -> R a -> R [a]
vectorOf n g = sequence (replicate n g)

-- The grammars ------------------------------------------------------------------------

genSmall :: Text -> R Small
genSmall p = do
  n <- choose 1 3
  let names = take n [p <> "S", p <> "A", p <> "B"]
      lbl = p <> "l"
  bodies <- mapM (\_ -> genAlts names lbl) names
  -- Every rule is reachable from S.
  let reach = if n > 1 then " / 'c' " <> T.unwords (drop 1 names) else ""
      rules = [nm <> " <- " <> b <> (if k == (0 :: Int) then reach else "") | (k, nm, b) <- zip3 [0 ..] names bodies]
      labelled = any (T.isInfixOf ("^" <> lbl)) bodies
  recover <- if labelled then chance 2 else pure False
  message <- if labelled then chance 3 else pure False
  expect <- chance 4
  expectRule <- elements names
  nomemo <- if n > 1 then chance 3 else pure False
  nomemoRule <- elements (drop 1 names ++ [p <> "S"])
  tok <- if n > 1 then chance 3 else pure False
  inl <- if n > 2 then chance 3 else pure False
  pure
    Small
      { smallPrefix = p
      , smallDirectives =
          -- The labels may reject valid input: the grammars are random.
          ["%safe " <> lbl | labelled]
            ++ ["%recover " <> lbl <> " " <> p <> "R" | recover]
            ++ ["%message " <> lbl <> " \"missing " <> p <> "\"" | message]
            ++ ["%expect " <> expectRule <> " \"" <> expectRule <> "\"" | expect]
            ++ ["%nomemo " <> nomemoRule | nomemo]
            ++ ["%token " <> p <> "A" | tok]
            ++ ["%inline " <> p <> "B" | inl]
      , -- The recovery rule consumes input: a recovery that consumes
        -- nothing lets a rule call itself at the same position without
        -- left recursion, and the parse does not end (the generated parser
        -- too).
        smallRules = rules ++ [p <> "R <- (!'c' .)+" | recover]
      }

genAlts :: [Text] -> Text -> R Text
genAlts names lbl = do
  k <- choose 1 3
  alts <- vectorOf k (genSeq names lbl True 3)
  pure (T.intercalate " / " alts)

-- A sequence; at the top of an alternative, its elements may be bound.
genSeq :: [Text] -> Text -> Bool -> Int -> R Text
genSeq names lbl top d = do
  k <- choose 1 3
  xs <- mapM (\i -> genItem names lbl top d i) [1 .. k]
  pure (T.unwords xs)

genItem :: [Text] -> Text -> Bool -> Int -> Int -> R Text
genItem names lbl top d i = do
  bind <- if top then chance 4 else pure False
  if bind
    then frequency [(2, (\n -> "x" <> T.pack (show i) <> ":" <> n) <$> elements names), (1, (\x -> "x" <> T.pack (show i) <> ":$(" <> x <> ")") <$> genSeq names lbl False (d - 1))]
    else genExpr names lbl d

genExpr :: [Text] -> Text -> Int -> R Text
genExpr names lbl d
  | d <= 0 = atom
  | otherwise =
      frequency
        [ (4, atom)
        , (1, (\x -> "(" <> x <> ")*") <$> sub)
        , (1, (\x -> "(" <> x <> ")?") <$> sub)
        , (1, (\x -> "(" <> x <> ")+") <$> sub)
        , (1, (\x -> "!(" <> x <> ")") <$> sub)
        , (1, (\x -> "&(" <> x <> ")") <$> sub)
        , (2, (\x y -> "(" <> x <> " / " <> y <> ")") <$> sub <*> sub)
        , (2, (\x -> "(" <> x <> " ^" <> lbl <> ")") <$> labelled)
        ]
  where
    sub = genSeq names lbl False (d - 1)
    -- The label is on the last element, an atom or a group: a label on a
    -- repetition or an option is left out, since the generator does not
    -- compile it when the label has a recovery rule and its value is not
    -- used (a bug of peg-codegen that ADR 0090 does not fix).
    labelled = do
      k <- choose 0 2
      xs <- vectorOf k (genExpr names lbl (d - 1))
      x <- frequency [(3, atom), (1, (\y z -> "(" <> y <> " / " <> z <> ")") <$> sub <*> sub)]
      pure (T.unwords (xs ++ [x]))
    atom =
      frequency
        [ (4, elements ["'a'", "'b'", "'c'", "'ab'"])
        , (1, elements ["[ab]", "[b-c]", ".", "!."])
        , (3, elements names)
        ]
